import React, { useState, useCallback } from 'react';
import WalletConnect from './components/WalletConnect';
import './App.css';

function App() {
  const [walletInfo, setWalletInfo] = useState(null);

  // Sử dụng useCallback để tránh việc hàm bị tạo lại gây vòng lặp kết nối
  const handleWalletConnected = useCallback((info) => {
    setWalletInfo(info);
  }, []);

  return (
    <div className="app">
      <header className="app-header">
        <div className="header-left">
          {/* Logo hoặc Menu phụ */}
        </div>
        <div className="header-center">
          <h1>🏛️ Auction DApp</h1>
          <p className="subtitle">Phiên bản đấu giá phi tập trung 2.0</p>
        </div>
        <div className="header-right">
          <WalletConnect onWalletConnected={handleWalletConnected} />
        </div>
      </header>

      <main className="app-main">
        {walletInfo && (
          <div className="welcome-section">
            <h2>🔥 Sàn Đấu Giá Đang Diễn Ra</h2>
            <div className="features-preview">
              <div className="feature-tag">📦 10 Sản phẩm mới</div>
              <div className="feature-tag">⏱️ Kết thúc sau 2h</div>
              <div className="feature-tag">💰 Giá cao nhất: 1.5 ETH</div>
            </div>
          </div>
        )}
      </main>

      <footer className="app-footer">
        <p>© 2026 Auction DApp - Được xây dựng trên Blockchain</p>
      </footer>
    </div>
  );
}

export default App;
